generated_pydough:
gymnast_hometowns = gymnasts.CALCULATE(
    hometown_for_gymnast=person.hometown
)

hometown_counts = gymnast_hometowns.PARTITION(
    name="hometown_group", by=hometown_for_gymnast
).CALCULATE(
    hometown_name=hometown_for_gymnast,
    num_gymnasts=COUNT(gymnast_hometowns)
)

most_common_hometown_result = hometown_counts.TOP_K(1, by=num_gymnasts.DESC()).CALCULATE(
    hometown_name=hometown_name
)

most_common_amenity_data = has_amenities.CALCULATE(
    amenity_name=dorm_amenity.amenity_name
).PARTITION(
    name="amenity_groups", 
    by=amenity_name
).CALCULATE(
    amenity_name=amenity_name,
    amenity_count=COUNT(has_amenities)
).TOP_K(1, by=amenity_count.DESC())

characteristic_counts = product_characteristic.CALCULATE(
    char_name=characteristic.characteristic_name
).PARTITION(
    name="char_groups",
    by=char_name
).CALCULATE(
    characteristic_name=char_name,
    characteristic_count=COUNT(product_characteristic)
).TOP_K(1, by=characteristic_count.DESC()).CALCULATE(
    characteristic_name=characteristic_name
)

most_liked_highschooler_name = highschoolers.CALCULATE(
    num_likes=COUNT(like)
).TOP_K(1, by=num_likes.DESC()).CALCULATE(
    name=name
)

smallest_claim_customer = insurance_and_eClaims.claim_header.TOP_K(1, by=amount_piad.ASC()).SINGULAR().policy.customer.CALCULATE(
    customer_details=customer_details
)

distinct_customers_who_bought_keyboard = customer.WHERE(
    HAS(customer_order.order_item.product.WHERE(product_name == 'keyboard')) == 1
).CALCULATE(
    customer_name=customer_name
)

top_artists_by_songs = songs.WHERE(
    HAS(artist) == 1 # Ensures songs have a valid artist linked via the simple_join
).PARTITION(
    name="artist_groups",
    by=artist_name # Group songs by their artist_name
).CALCULATE(
    artist_name=artist_name, # Select the artist's name from the partition key
    num_of_songs=COUNT(songs) # Count songs within each artist group
).TOP_K(3, by=num_of_songs.DESC()) # Select the top 3 artists by song count

product_info = product.CALCULATE(
    color_desc=ref_color.color_description
)

least_common_color = product_info.PARTITION(
    name="colors", by=color_desc
).CALCULATE(
    color_description=color_desc,
    num_products=COUNT(product)
).TOP_K(1, by=num_products.ASC())

research_documents_send_dates = document.WHERE(
    (grant.grant_amount > 5000) &
    (grant.organisation.organisation_type_join.organisation_type_description == 'Research')
).CALCULATE(
    send_date=sent_date
)

shop_with_greatest_quantity = shops.CALCULATE(
    shop_name=shop_name,
    total_quantity=SUM(stocks.quantity)
).TOP_K(1, by=total_quantity.DESC()).CALCULATE(
    shop_name=shop_name
)

project_details_by_organisation = project.CALCULATE(
    project_details=project_details
)

most_papers_inst = insts.CALCULATE(
    inst_name=name,
    num_papers=COUNT(authorships)
).TOP_K(1, by=num_papers.DESC()).CALCULATE(
    institution_name=inst_name
)

artist_bangla_song_data = artists.CALCULATE(
    artist_name=artist_name,
    num_bangla_songs=COUNT(songs.WHERE(languages == 'bangla'))
)

top_artists_by_bangla_songs = artist_bangla_song_data.TOP_K(
    3, 
    by=(num_bangla_songs.DESC(), artist_name.ASC()) # Primary sort by song count (DESC), secondary by artist name (ASC) for ties
).CALCULATE(
    artist_name=artist_name
)

instructor_advising_math_students = advisors.WHERE(
    student.department.dept_name == "Math"
).CALCULATE(
    instructor_name=instructor.name,
    student_total_credits=student.tot_cred
).ORDER_BY(student_total_credits.ASC())

filtered_apartments_for_analysis = apartment.WHERE(
    bathroom_count > 1
).CALCULATE(
    apartment_id_for_count=apt_id,
    apartment_type_code_for_group=apt_type_code
)

apartment_type_counts = filtered_apartments_for_analysis.PARTITION(
    name="apartment_type_groups",
    by=(apartment_type_code_for_group)
).CALCULATE(
    apt_type_code=apartment_type_code_for_group,
    apt_count=COUNT(filtered_apartments_for_analysis.apartment_id_for_count)
)

most_common_apartment_type = apartment_type_counts.TOP_K(
    1,
    by=apt_count.DESC()
).CALCULATE(
    apt_type_code=apt_type_code
)

customers_without_latte = customer.WHERE(
    HASNOT(customer_order.order_item.product.WHERE(product_details == 'Latte')) == 1
).CALCULATE(
    customer_name=customer_name
)

music_festival_results_counts = music_festivals.PARTITION(
    name="results_group", by=(result)
).CALCULATE(
    result=result,
    num_music_festivals=COUNT(music_festivals)
).ORDER_BY(num_music_festivals.DESC())

most_active_party_email = party.CALCULATE(
    party_email=party_email,
    num_services=COUNT(party_service)
).TOP_K(1, by=num_services.DESC()).CALCULATE(
    party_email=party_email
)

david_shieber_sports_summary = students.WHERE(
    (fname == 'David') & (lname == 'Shieber')
).CALCULATE(
    total_hours_per_week=SUM(sportsinfos.hoursperweek),
    total_games_played=SUM(sportsinfos.gamesplayed)
)

result = dorm_1.dorms.WHERE(
    (HAS(has_amenities.WHERE(dorm_amenity.amenity_name == "TV Lounge")) == 1)
    & (HASNOT(has_amenities.WHERE(dorm_amenity.amenity_name == "Study Room")) == 1)
).CALCULATE(
    dorm_name=dorm_name
)

result = instrument.WHERE(
    (instrument.band.lastname == "Heilo") &
    (instrument.song.title == "Le Pop")
).CALCULATE(
    instrument_used=instrument.instrument
)

media_type_counts = tracks.CALCULATE(
    media_type_name=mediatype.name
).PARTITION(
    name="media_type_groups", by=media_type_name
).CALCULATE(
    media_type_name=media_type_name,
    track_count=COUNT(tracks)
).TOP_K(1, by=track_count.ASC())

# Step 1: Calculate the global average checking balance as a scalar value
global_average_checking_balance = CHECKING.CALCULATE(
    avg_balance=RELAVG(balance)
).SINGULAR().avg_balance

# Step 2: Find accounts whose checking balance is below this global average
accounts_below_average_checking = CHECKING.WHERE(
    balance < global_average_checking_balance
).account.CALCULATE(
    account_name=name
)

result = document.WHERE(
    (document.document_type.document_description == 'Regular') |
    (document.grant.grant_amount > 100)
).CALCULATE(
    response_received_date=response_received_date
)

enrollment_data = college_1.enrolls.CALCULATE(
    department_name_from_enrollment = CLASS.COURSE.DEPARTMENT.dept_name
)

department_enrollment_counts = enrollment_data.PARTITION(
    name="department_groups",
    by=department_name_from_enrollment
).CALCULATE(
    department_name_alias=department_name_from_enrollment,
    total_enrollments=COUNT(enrollment_data)
)

department_with_most_students = department_enrollment_counts.TOP_K(1, by=total_enrollments.DESC()).CALCULATE(
    department_name=department_name_alias
)
